-- Performance: evidence-based reviews, confidential drafts and immutable released records.
create schema performance_internal;
revoke all on schema performance_internal from public,anon;grant usage on schema performance_internal to authenticated;
create function performance_internal.member(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select auth.uid() is not null and private.network_policy_ok(p_org) and exists(select 1 from public.employees where organization_id=p_org and user_id=auth.uid() and status in('active','leave')) and (not private.user_requires_mfa(p_org,auth.uid()) or coalesce(auth.jwt()->>'aal','aal1')='aal2'); $$;
create function performance_internal.hr(p_org uuid) returns boolean language sql stable security definer set search_path='' as $$ select performance_internal.member(p_org) and private.has_permission(p_org,'appraisal.manage_cycles'); $$;
create function performance_internal.require_hr(p_org uuid) returns void language plpgsql security definer set search_path='' as $$ begin if not coalesce(performance_internal.hr(p_org),false) then raise exception using errcode='42501',message='Performance administration permission required';end if;perform private.assert_step_up(p_org);end; $$;
alter table public.appraisal_questions add column required boolean not null default true,add column is_active boolean not null default true;
alter table public.appraisal_sections add column is_active boolean not null default true;
alter table public.appraisal_cycles add column review_period_start date,add column review_period_end date,add column form_snapshot jsonb,add column cancel_reason text,add column closed_at timestamptz,add column revision integer not null default 1;
alter table public.appraisal_instances add column form_snapshot jsonb,add column employee_name text,add column cycle_name text,add column review_period_start date,add column review_period_end date,add column opening_date date,add column acknowledgement_due date,add column released_at timestamptz,add column cancel_reason text,add column query_status text not null default 'none' check(query_status in('none','open','resolved'));
alter table public.appraisal_reviewers add column reviewer_name text,add column due_date date,add column draft_version integer not null default 0,add column resolution_reason text;
alter table public.appraisal_signoffs add column disposition text not null default 'received' check(disposition in('received','received_with_comments','disagree'));
create unique index appraisal_cycle_subject_once_idx on public.appraisal_instances(cycle_id,employee_id) where cycle_id is not null;
create index appraisal_instance_cycle_created_idx on public.appraisal_instances(cycle_id,created_at desc,id);
alter table public.appraisal_reviewers drop constraint appraisal_reviewers_instance_id_role_reviewer_user_id_key;
create unique index appraisal_current_reviewer_once_idx on public.appraisal_reviewers(instance_id,role,reviewer_user_id) where status<>'skipped';
create unique index appraisal_current_sequence_once_idx on public.appraisal_reviewers(instance_id,sequence) where status<>'skipped';
create index appraisal_response_reviewer_idx on public.appraisal_responses(reviewer_id);
create function performance_internal.reviewer_valid(p_reviewer uuid) returns boolean language sql stable security definer set search_path='' as $$
 select exists(select 1 from public.appraisal_reviewers r join public.appraisal_instances i on i.id=r.instance_id join public.employees actor on actor.user_id=r.reviewer_user_id and actor.organization_id=i.organization_id and actor.status in('active','leave') where r.id=p_reviewer and r.status<>'skipped' and case r.role when 'self' then actor.id=i.employee_id and private.user_has_permission(i.organization_id,r.reviewer_user_id,'appraisal.complete_self') when 'hr' then actor.id<>i.employee_id and private.user_has_permission(i.organization_id,r.reviewer_user_id,'appraisal.manage_cycles') when 'peer' then actor.id<>i.employee_id else actor.id<>i.employee_id and (private.user_has_permission(i.organization_id,r.reviewer_user_id,'appraisal.manage_cycles') or (private.user_has_permission(i.organization_id,r.reviewer_user_id,'appraisal.review_direct_reports') and exists(select 1 from public.management_scope where actor_user_id=r.reviewer_user_id and employee_id=i.employee_id))) end);
$$;
create function performance_internal.reader(p_instance uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.appraisal_instances i where i.id=p_instance and performance_internal.member(i.organization_id) and (performance_internal.hr(i.organization_id) or exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()) or (private.has_permission(i.organization_id,'appraisal.review_direct_reports') and private.in_management_scope(i.employee_id)) or exists(select 1 from public.appraisal_reviewers r where r.instance_id=i.id and r.reviewer_user_id=auth.uid() and performance_internal.reviewer_valid(r.id)))); $$;
create function performance_internal.response_reader(p_reviewer uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.appraisal_reviewers r join public.appraisal_instances i on i.id=r.instance_id where r.id=p_reviewer and performance_internal.reader(i.id) and (r.reviewer_user_id=auth.uid() and performance_internal.reviewer_valid(r.id) or (r.status='submitted' and (i.released_at is not null or performance_internal.hr(i.organization_id) or exists(select 1 from public.appraisal_reviewers viewer where viewer.instance_id=i.id and viewer.reviewer_user_id=auth.uid() and performance_internal.reviewer_valid(viewer.id) and viewer.sequence>r.sequence))))); $$;

create function performance_internal.template_snapshot(p_template uuid) returns jsonb language sql stable security definer set search_path='' as $$ select jsonb_build_object('id',t.id,'name',t.name,'description',t.description,'rating_scale',t.rating_scale,'sections',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'title',s.title,'sequence',s.sequence,'questions',coalesce((select jsonb_agg(to_jsonb(q) order by q.sequence,q.id) from public.appraisal_questions q where q.section_id=s.id and q.is_active),'[]'::jsonb)) order by s.sequence,s.id) from public.appraisal_sections s where s.template_id=t.id and s.is_active),'[]'::jsonb)) from public.appraisal_templates t where t.id=p_template; $$;
-- Existing snapshots can only reflect the available current template; no historical data is invented.
update public.appraisal_instances i set form_snapshot=performance_internal.template_snapshot(i.template_id),employee_name=(select concat_ws(' ',coalesce(nullif(trim(e.preferred_name),''),e.first_name),e.last_name) from public.employees e where e.id=i.employee_id),cycle_name=coalesce(i.label,(select name from public.appraisal_cycles where id=i.cycle_id)),opening_date=(select start_date from public.appraisal_cycles where id=i.cycle_id),acknowledgement_due=(select acknowledgement_due from public.appraisal_cycles where id=i.cycle_id),review_period_start=(select review_period_start from public.appraisal_cycles where id=i.cycle_id),review_period_end=(select review_period_end from public.appraisal_cycles where id=i.cycle_id),released_at=case when i.status in('employee_acknowledgement','complete') then coalesce(i.acknowledged_at,i.created_at) end;
update public.appraisal_reviewers r set reviewer_name=concat_ws(' ',coalesce(nullif(trim(e.preferred_name),''),e.first_name),e.last_name) from public.appraisal_instances i,public.employees e where i.id=r.instance_id and e.user_id=r.reviewer_user_id and e.organization_id=i.organization_id;

do $$ declare p record;begin for p in select tablename,policyname from pg_policies where schemaname='public' and tablename in('appraisal_instances','appraisal_reviewers','appraisal_responses','appraisal_signoffs','appraisal_cycles') loop execute format('drop policy %I on public.%I',p.policyname,p.tablename);end loop;end $$;
create policy "scoped performance instances" on public.appraisal_instances for select to authenticated using(performance_internal.reader(id));
create policy "scoped performance reviewers" on public.appraisal_reviewers for select to authenticated using(performance_internal.reader(instance_id));
create policy "private performance responses" on public.appraisal_responses for select to authenticated using(performance_internal.response_reader(reviewer_id));
create policy "released performance signoffs" on public.appraisal_signoffs for select to authenticated using(performance_internal.reader(instance_id));
create policy "HR reads performance cycles" on public.appraisal_cycles for select to authenticated using(performance_internal.hr(organization_id));
create policy "HR creates performance cycles" on public.appraisal_cycles for insert to authenticated with check(performance_internal.hr(organization_id));
create policy "HR edits performance cycles" on public.appraisal_cycles for update to authenticated using(performance_internal.hr(organization_id)) with check(performance_internal.hr(organization_id));
grant select on public.appraisal_templates,public.appraisal_sections,public.appraisal_questions,public.appraisal_cycles,public.appraisal_instances,public.appraisal_reviewers,public.appraisal_responses,public.appraisal_signoffs,public.appraisal_cycle_progress_v to authenticated;
revoke insert,update,delete on public.appraisal_instances,public.appraisal_reviewers,public.appraisal_responses,public.appraisal_signoffs from authenticated;
grant insert,update on public.appraisal_templates,public.appraisal_sections,public.appraisal_questions,public.appraisal_cycles to authenticated;
revoke delete on public.appraisal_templates,public.appraisal_sections,public.appraisal_questions,public.appraisal_cycles from authenticated;

create function performance_internal.validate_scale(p_scale jsonb) returns void language plpgsql immutable set search_path='' as $$ declare item jsonb;begin
 if jsonb_typeof(p_scale) is distinct from 'array' or jsonb_array_length(p_scale)>20 then raise exception 'Use an array of up to 20 rating options';end if;
 for item in select * from jsonb_array_elements(p_scale) loop if jsonb_typeof(item->'value') is distinct from 'number' or jsonb_typeof(item->'label') is distinct from 'string' or length(trim(coalesce(item->>'label',''))) not between 1 and 100 or ((item->>'value')::numeric not between -9999 and 9999 or (item->>'value')::numeric<>round((item->>'value')::numeric,2)) then raise exception 'Check rating values and labels';end if;end loop;
 if (select count(*) from jsonb_array_elements(p_scale))<>(select count(distinct (value->>'value')::numeric) from jsonb_array_elements(p_scale)) then raise exception 'Rating values must be unique';end if;
end; $$;
create function performance_internal.setup_guard() returns trigger language plpgsql security definer set search_path='' as $$ declare org uuid;tid uuid;begin
 if tg_table_name in('appraisal_templates','appraisal_cycles') then if tg_op='DELETE' then org:=old.organization_id;else org:=new.organization_id;end if;
 elsif tg_table_name='appraisal_sections' then if tg_op='DELETE' then tid:=old.template_id;else tid:=new.template_id;end if;select organization_id into org from public.appraisal_templates where id=tid;
 else if tg_op='DELETE' then select s.template_id into tid from public.appraisal_sections s where s.id=old.section_id;else select s.template_id into tid from public.appraisal_sections s where s.id=new.section_id;end if;select organization_id into org from public.appraisal_templates where id=tid;end if;
 if tg_op='DELETE' and (org is null or not exists(select 1 from public.organizations where id=org)) then return old;end if;
 if auth.uid() is not null and pg_trigger_depth()=1 then perform performance_internal.require_hr(org);end if;
 if tg_table_name in('appraisal_sections','appraisal_questions') then perform 1 from public.appraisal_templates where id=tid for update;end if;
 if tg_op='DELETE' then raise exception 'Retain performance history; archive the template or cancel a draft cycle';end if;
 if tg_table_name='appraisal_templates' then new.name:=trim(new.name);if length(new.name) not between 1 and 120 or length(coalesce(new.description,''))>3000 then raise exception 'Check template name and description';end if;perform performance_internal.validate_scale(new.rating_scale);if tg_op='UPDATE' and new.organization_id<>old.organization_id then raise exception 'Template organization is immutable';end if;
 elsif tg_table_name='appraisal_sections' then new.title:=trim(new.title);if length(new.title) not between 1 and 160 then raise exception 'A section title must have 1–160 characters';end if;if tg_op='UPDATE' and new.template_id<>old.template_id then raise exception 'Sections cannot move to a different template';end if;
 elsif tg_table_name='appraisal_questions' then
  new.prompt:=trim(new.prompt);if length(new.prompt) not between 1 and 2000 or new.weight<0 or new.weight>100 then raise exception 'Check question prompt and weight';end if;
  if tg_op='UPDATE' and new.section_id<>old.section_id then raise exception 'Questions cannot move to another section';end if;
  if new.question_type='multiple_choice' then if jsonb_typeof(new.options) is distinct from 'array' or jsonb_array_length(new.options) not between 2 and 20 or exists(select 1 from jsonb_array_elements(new.options)x where jsonb_typeof(x)<>'string' or length(trim(x#>>'{}')) not between 1 and 200) or (select count(distinct trim(value#>>'{}')) from jsonb_array_elements(new.options))<>jsonb_array_length(new.options) then raise exception 'Multiple choice needs 2–20 distinct nonempty text options';end if;end if;
  if new.question_type='numeric_rating' and new.options is not null and (jsonb_typeof(new.options)<>'object' or jsonb_typeof(new.options->'min') is distinct from 'number' or jsonb_typeof(new.options->'max') is distinct from 'number' or (new.options->>'min')::numeric >= (new.options->>'max')::numeric or (new.options->>'min')::numeric < -9999 or (new.options->>'max')::numeric > 9999) then raise exception 'Numeric ratings need a valid minimum and maximum';end if;
 else
  if new.repeat_interval<>'none' then raise exception 'Automatic recurrence is not enabled; create the next reviewed cycle explicitly';end if;
  new.name:=trim(new.name);if length(new.name) not between 1 and 160 or not exists(select 1 from public.appraisal_templates where id=new.template_id and organization_id=new.organization_id and (is_active or new.status in('closed','cancelled'))) then raise exception 'Choose an active template in this organization and a cycle name';end if;
  if tg_op='UPDATE' and old.status<>'draft' and (to_jsonb(new)-'status'-'cancel_reason'-'closed_at') is distinct from (to_jsonb(old)-'status'-'cancel_reason'-'closed_at') then raise exception 'Launched cycle settings and deadlines are immutable';end if;
  if new.review_period_start is not null and new.review_period_end is not null and new.review_period_end<new.review_period_start then raise exception 'Review period end must follow its start';end if;
  if coalesce(new.self_review_due,new.start_date)<new.start_date or coalesce(new.supervisor_review_due,new.self_review_due,new.start_date)<coalesce(new.self_review_due,new.start_date) or coalesce(new.manager_review_due,new.supervisor_review_due,new.self_review_due,new.start_date)<coalesce(new.supervisor_review_due,new.self_review_due,new.start_date) or coalesce(new.acknowledgement_due,new.manager_review_due,new.supervisor_review_due,new.self_review_due,new.start_date)<coalesce(new.manager_review_due,new.supervisor_review_due,new.self_review_due,new.start_date) then raise exception 'Due dates must follow the cycle start and review order';end if;
 end if;
 return new;
end; $$;
create trigger performance_template_guard before insert or update or delete on public.appraisal_templates for each row execute function performance_internal.setup_guard();
create trigger performance_section_guard before insert or update or delete on public.appraisal_sections for each row execute function performance_internal.setup_guard();
create trigger performance_question_guard before insert or update or delete on public.appraisal_questions for each row execute function performance_internal.setup_guard();
create trigger performance_cycle_guard before insert or update or delete on public.appraisal_cycles for each row execute function performance_internal.setup_guard();

create function performance_internal.validate_filter(p_org uuid,p_filter jsonb) returns void language plpgsql security definer set search_path='' as $$ declare k text;x text;begin
 if jsonb_typeof(p_filter) is distinct from 'object' then raise exception 'Cycle targeting must be an object';end if;
 for k in select jsonb_object_keys(p_filter) loop
  if k not in('employee_ids','org_unit_ids','position_ids','employment_types','status') or jsonb_typeof(p_filter->k)<>'array' or jsonb_array_length(p_filter->k)>2000 then raise exception 'Unsupported cycle targeting field';end if;
  for x in select jsonb_array_elements_text(p_filter->k) loop
   if k='employee_ids' and not exists(select 1 from public.employees where id=x::uuid and organization_id=p_org) or k='org_unit_ids' and not exists(select 1 from public.org_units where id=x::uuid and organization_id=p_org) or k='position_ids' and not exists(select 1 from public.positions where id=x::uuid and organization_id=p_org) or k='employment_types' and x not in('full_time','part_time','contract','temporary','intern') or k='status' and x not in('active','leave') then raise exception 'Choose valid employees, organisational units, positions, employment types and eligible statuses from this organization';end if;
  end loop;
 end loop;
end; $$;
create function performance_internal.roster(p_cycle uuid) returns table(employee_id uuid,employee_name text,user_id uuid,supervisor_user uuid,manager_user uuid,warning text) language plpgsql stable security definer set search_path='' as $$ declare c public.appraisal_cycles;begin
 select * into c from public.appraisal_cycles where id=p_cycle;perform performance_internal.require_hr(c.organization_id);perform performance_internal.validate_filter(c.organization_id,c.employee_filter);
 return query select e.id,concat_ws(' ',coalesce(nullif(trim(e.preferred_name),''),e.first_name),e.last_name),e.user_id,sup.user_id,mgr.user_id,case when sup.user_id is null and mgr.user_id is null then 'No eligible leader account; HR review will be required' end
 from public.employees e
 left join lateral(select a.* from public.employee_assignments a where a.employee_id=e.id and a.start_date<=coalesce(c.review_period_end,private.org_today(c.organization_id)) and (a.end_date is null or a.end_date>=coalesce(c.review_period_end,private.org_today(c.organization_id))) order by a.start_date desc,a.id limit 1) target on true
 left join lateral(select a.* from public.employee_assignments a where a.employee_id=e.id and a.start_date<=private.org_today(c.organization_id) and (a.end_date is null or a.end_date>=private.org_today(c.organization_id)) order by a.start_date desc,a.id limit 1) current_assignment on true
 left join public.employees sup on sup.id=current_assignment.supervisor_employee_id and sup.organization_id=c.organization_id and sup.status in('active','leave') and sup.id<>e.id
 left join public.employees mgr on mgr.id=current_assignment.manager_employee_id and mgr.organization_id=c.organization_id and mgr.status in('active','leave') and mgr.id<>e.id
 where e.organization_id=c.organization_id and e.status in('active','leave') and e.user_id is not null and (c.review_period_end is null or e.hire_date is null or e.hire_date<=c.review_period_end)
 and (not c.employee_filter?'employee_ids' or c.employee_filter->'employee_ids'='[]'::jsonb or c.employee_filter->'employee_ids' ? e.id::text)
 and (not c.employee_filter?'org_unit_ids' or c.employee_filter->'org_unit_ids'='[]'::jsonb or c.employee_filter->'org_unit_ids' ? target.org_unit_id::text)
 and (not c.employee_filter?'position_ids' or c.employee_filter->'position_ids'='[]'::jsonb or c.employee_filter->'position_ids' ? target.position_id::text)
 and (not c.employee_filter?'employment_types' or c.employee_filter->'employment_types'='[]'::jsonb or c.employee_filter->'employment_types' ? target.employment_type)
 and (not c.employee_filter?'status' or c.employee_filter->'status'='[]'::jsonb or c.employee_filter->'status' ? e.status)
 order by e.last_name,e.first_name,e.id;
end; $$;

create function performance_internal.launch(p_cycle uuid) returns setof public.appraisal_instances language plpgsql security definer set search_path='' as $$ declare c public.appraisal_cycles;t public.appraisal_templates;snapshot jsonb;emp record;i public.appraisal_instances;seq smallint;uid uuid;n integer:=0;begin
 select * into c from public.appraisal_cycles where id=p_cycle for update;perform performance_internal.require_hr(c.organization_id);
 if c.status='open' then return query select * from public.appraisal_instances where cycle_id=c.id order by id;return;end if;
 if c.status<>'draft' then raise exception 'This cycle is already closed or cancelled';end if;
 select * into t from public.appraisal_templates where id=c.template_id and organization_id=c.organization_id and is_active for update;if t.id is null then raise exception 'Choose an active template in this organization';end if;
 snapshot:=performance_internal.template_snapshot(t.id);
 if not exists(select 1 from jsonb_array_elements(snapshot->'sections')section cross join lateral jsonb_array_elements(section->'questions')q) then raise exception 'Add at least one question before launching';end if;
 if exists(select 1 from jsonb_array_elements(snapshot->'sections')section cross join lateral jsonb_array_elements(section->'questions')q where q->>'question_type'='rating_scale') and jsonb_array_length(snapshot->'rating_scale')<2 then raise exception 'Configure at least two rating options for scale questions';end if;
 for emp in select * from performance_internal.roster(c.id) loop
  n:=n+1;if n>2000 then raise exception 'Limit a cycle to 2000 eligible employees';end if;
  insert into public.appraisal_instances(organization_id,cycle_id,template_id,employee_id,label,form_snapshot,employee_name,cycle_name,review_period_start,review_period_end,opening_date,acknowledgement_due) values(c.organization_id,c.id,t.id,emp.employee_id,c.name,snapshot,emp.employee_name,c.name,c.review_period_start,c.review_period_end,c.start_date,c.acknowledgement_due) returning * into i;
  insert into public.appraisal_reviewers(instance_id,role,reviewer_user_id,sequence,reviewer_name,due_date) values(i.id,'self',emp.user_id,1,emp.employee_name,c.self_review_due);seq:=1;
  if emp.supervisor_user is not null then seq:=seq+1;insert into public.appraisal_reviewers(instance_id,role,reviewer_user_id,sequence,reviewer_name,due_date) select i.id,'supervisor',emp.supervisor_user,seq,concat_ws(' ',coalesce(nullif(trim(preferred_name),''),first_name),last_name),c.supervisor_review_due from public.employees where organization_id=c.organization_id and user_id=emp.supervisor_user limit 1;end if;
  if emp.manager_user is not null and emp.manager_user is distinct from emp.supervisor_user then seq:=seq+1;insert into public.appraisal_reviewers(instance_id,role,reviewer_user_id,sequence,reviewer_name,due_date) select i.id,'manager',emp.manager_user,seq,concat_ws(' ',coalesce(nullif(trim(preferred_name),''),first_name),last_name),c.manager_review_due from public.employees where organization_id=c.organization_id and user_id=emp.manager_user limit 1;end if;
  if seq=1 then uid:=case when emp.user_id<>auth.uid() then auth.uid() end;insert into public.appraisal_reviewers(instance_id,role,reviewer_user_id,sequence,reviewer_name,due_date) select i.id,'hr',uid,2,case when uid is not null then concat_ws(' ',coalesce(nullif(trim(preferred_name),''),first_name),last_name) end,c.manager_review_due from public.employees where organization_id=c.organization_id and user_id=auth.uid() limit 1;end if;
  perform private.create_notification(c.organization_id,emp.user_id,emp.employee_id,'performance.assigned','A performance checkpoint is ready','Open Performance for the review period, questions and deadlines.','/appraisals/'||i.id,jsonb_build_object('instance_id',i.id));
  return next i;
 end loop;
 if n=0 then raise exception 'No eligible employees match this cycle. Review targeting, account links and the review period';end if;
 update public.appraisal_cycles set status='open',form_snapshot=snapshot where id=c.id;
 perform private.log_audit_event(c.organization_id,'APPRAISAL_CYCLE_LAUNCHED','appraisal_cycle',c.id,null,jsonb_build_object('employees',n));return;
end; $$;
create or replace function public.launch_appraisal_cycle(p_cycle_id uuid) returns setof public.appraisal_instances language sql security invoker set search_path='' as $$ select * from performance_internal.launch(p_cycle_id); $$;
create function performance_internal.lock_instance(p_instance uuid) returns public.appraisal_instances language plpgsql security definer set search_path='' as $$ declare i public.appraisal_instances;c public.appraisal_cycles;begin
 select * into i from public.appraisal_instances where id=p_instance;if i.id is null or not performance_internal.reader(i.id) then raise exception using errcode='42501',message='Performance record unavailable';end if;
 if i.cycle_id is not null then select * into c from public.appraisal_cycles where id=i.cycle_id for share;if c.status not in('open','closed','cancelled') then raise exception 'The cycle is not open for review';end if;end if;
 select * into i from public.appraisal_instances where id=p_instance for update;
 if i.status='cancelled' then raise exception 'This checkpoint was cancelled';end if;perform private.assert_step_up(i.organization_id);return i;
end; $$;
create function performance_internal.stage_writer(p_reviewer uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.appraisal_reviewers r join public.appraisal_instances i on i.id=r.instance_id left join public.appraisal_cycles c on c.id=i.cycle_id where r.id=p_reviewer and r.reviewer_user_id=auth.uid() and r.status='pending' and performance_internal.member(i.organization_id) and performance_internal.reviewer_valid(r.id) and i.status not in('complete','cancelled') and (c.id is null or (c.status='open' and c.start_date<=private.org_today(i.organization_id))) and not exists(select 1 from public.appraisal_reviewers earlier where earlier.instance_id=i.id and earlier.status='pending' and earlier.sequence<r.sequence)); $$;
create function performance_internal.question(p_instance uuid,p_question uuid) returns jsonb language sql stable security definer set search_path='' as $$ select q from public.appraisal_instances i cross join lateral jsonb_array_elements(i.form_snapshot->'sections')section cross join lateral jsonb_array_elements(section->'questions')q where i.id=p_instance and q->>'id'=p_question::text; $$;
create function performance_internal.validate_answer(p_instance uuid,p_question uuid,p_answer jsonb,p_strict boolean default true) returns void language plpgsql security definer set search_path='' as $$ declare q jsonb;scale jsonb;num numeric;begin
 q:=performance_internal.question(p_instance,p_question);if q is null then raise exception 'Question does not belong to this checkpoint snapshot';end if;
 if p_answer is null or p_answer='null'::jsonb or p_answer='""'::jsonb then return;end if;
 if q->>'question_type' in('numeric_rating','rating_scale') then
  if jsonb_typeof(p_answer)<>'number' then raise exception 'Rating answers must be numeric';end if;num:=(p_answer#>>'{}')::numeric;if num<>round(num,2) then raise exception 'Use at most two decimal places';end if;
  if q->>'question_type'='rating_scale' then select form_snapshot->'rating_scale' into scale from public.appraisal_instances where id=p_instance;if not exists(select 1 from jsonb_array_elements(scale)x where (x->>'value')::numeric=num) then raise exception 'Choose a value from the recorded rating scale';end if;
  elsif num<coalesce((q->'options'->>'min')::numeric,1) or num>coalesce((q->'options'->>'max')::numeric,5) then raise exception 'Numeric rating is outside the recorded bounds';end if;
 elsif q->>'question_type'='yes_no' then if jsonb_typeof(p_answer)<>'boolean' then raise exception 'Choose Yes or No';end if;
 elsif q->>'question_type'='multiple_choice' then if jsonb_typeof(p_answer)<>'string' or not(q->'options' ? (p_answer#>>'{}')) then raise exception 'Choose a configured option';end if;
 elsif q->>'question_type'='goal' then
  if jsonb_typeof(p_answer)<>'object' or length(coalesce(p_answer->>'title',''))>200 or length(coalesce(p_answer->>'measure',''))>2000 or length(coalesce(p_answer->>'support',''))>2000 or exists(select 1 from jsonb_object_keys(p_answer)k where k not in('title','measure','target_date','support')) or exists(select 1 from jsonb_each(p_answer) f where f.value<>'null'::jsonb and jsonb_typeof(f.value)<>'string') or (nullif(p_answer->>'target_date','') is not null and private.safe_import_date(p_answer->>'target_date') is null) then raise exception 'Check the goal fields and target date';end if;
  if p_strict and (length(trim(coalesce(p_answer->>'title','')))<3 or length(trim(coalesce(p_answer->>'measure','')))<3 or private.safe_import_date(p_answer->>'target_date') is null) then raise exception 'Goals need a title, measurable success criteria and target date';end if;
 else if jsonb_typeof(p_answer)<>'string' or length(trim(p_answer#>>'{}')) not between 1 and 4000 then raise exception 'Text answers must have 1–4000 characters';end if;end if;
end; $$;
create function performance_internal.advance(p_instance uuid) returns public.appraisal_instances language plpgsql security definer set search_path='' as $$ declare i public.appraisal_instances;r public.appraisal_reviewers;uid uuid;begin
 select * into i from public.appraisal_instances where id=p_instance;
 select * into r from public.appraisal_reviewers where instance_id=i.id and status='pending' order by sequence,id limit 1;
 if r.id is null then
  if not exists(select 1 from public.appraisal_reviewers where instance_id=i.id and role<>'self' and status='submitted') then raise exception 'At least one independent reviewer must complete this checkpoint';end if;
  update public.appraisal_instances set status='employee_acknowledgement',released_at=coalesce(released_at,now()) where id=i.id returning * into i;select user_id into uid from public.employees where id=i.employee_id;
  if uid is not null then perform private.create_notification(i.organization_id,uid,i.employee_id,'performance.released','Your performance feedback is ready','Read the completed reviews and record your response. Acknowledgement does not require agreement.','/appraisals/'||i.id,jsonb_build_object('instance_id',i.id));end if;
 else
  update public.appraisal_instances set status=case r.role when 'self' then 'open' when 'supervisor' then 'supervisor_review' else 'manager_review' end where id=i.id returning * into i;
  if r.reviewer_user_id is not null then perform private.create_notification(i.organization_id,r.reviewer_user_id,i.employee_id,'performance.stage_ready','A review stage is ready','Open Performance to review the checkpoint and deadlines.','/appraisals/'||i.id,jsonb_build_object('instance_id',i.id));end if;
 end if;return i;
end; $$;
create function performance_internal.submit_stage(p_reviewer uuid) returns public.appraisal_instances language plpgsql security definer set search_path='' as $$ declare r public.appraisal_reviewers;i public.appraisal_instances;q jsonb;answer jsonb;source public.appraisal_responses;proposed_goal uuid;begin
 select * into r from public.appraisal_reviewers where id=p_reviewer;i:=performance_internal.lock_instance(r.instance_id);
 select * into r from public.appraisal_reviewers where id=p_reviewer for update;
 if not performance_internal.stage_writer(r.id) then raise exception 'This is not your current, eligible review stage';end if;
 for q in select question from jsonb_array_elements(i.form_snapshot->'sections')section cross join lateral jsonb_array_elements(section->'questions')question loop
  if coalesce((q->>'required')::boolean,true) and not exists(select 1 from public.appraisal_responses where reviewer_id=r.id and question_id=(q->>'id')::uuid and response_json is not null and response_json<>'null'::jsonb and response_json<>'""'::jsonb) then raise exception 'Complete every required question before submitting';end if;
  select response_json into answer from public.appraisal_responses where reviewer_id=r.id and question_id=(q->>'id')::uuid;if answer is not null then perform performance_internal.validate_answer(i.id,(q->>'id')::uuid,answer,true);end if;
 end loop;
 update public.appraisal_reviewers set status='submitted',submitted_at=now() where id=r.id;
 if r.role='self' then for source in select * from public.appraisal_responses where reviewer_id=r.id loop
  if performance_internal.question(i.id,source.question_id)->>'question_type'='goal' then
   insert into public.performance_goals(instance_id,organization_id,employee_id,title,measure,target_date,support,created_by,source_response_id) values(i.id,i.organization_id,i.employee_id,source.response_json->>'title',source.response_json->>'measure',(source.response_json->>'target_date')::date,source.response_json->>'support',auth.uid(),source.id) on conflict(source_response_id) do nothing returning id into proposed_goal;
   if proposed_goal is not null then insert into public.performance_goal_events(goal_id,instance_id,kind,note,progress,created_by,actor_name) values(proposed_goal,i.id,'propose','Proposed from submitted self-review',0,auth.uid(),coalesce(r.reviewer_name,'Employee'));end if;
  end if;
 end loop;end if;
 perform private.log_audit_event(i.organization_id,'APPRAISAL_STAGE_SUBMITTED','appraisal_instance',i.id,null,jsonb_build_object('reviewer_id',r.id,'role',r.role));return performance_internal.advance(i.id);
end; $$;
create table performance_internal.review_retry_state(reviewer_id uuid primary key references public.appraisal_reviewers(id),request_id uuid not null,payload jsonb not null);alter table performance_internal.review_retry_state enable row level security;revoke all on performance_internal.review_retry_state from public,anon,authenticated;
create function performance_internal.save_review(p_reviewer uuid,p_answers jsonb,p_version integer,p_request uuid,p_submit boolean) returns jsonb language plpgsql security definer set search_path='' as $$ declare r public.appraisal_reviewers;i public.appraisal_instances;k text;a jsonb;payload jsonb;retry performance_internal.review_retry_state;begin
 select * into r from public.appraisal_reviewers where id=p_reviewer;i:=performance_internal.lock_instance(r.instance_id);select * into r from public.appraisal_reviewers where id=p_reviewer for update;
 if r.reviewer_user_id is distinct from auth.uid() or not performance_internal.reviewer_valid(r.id) then raise exception 'You are not authorized to write this review';end if;
 if p_request is null or p_submit is null or jsonb_typeof(p_answers) is distinct from 'object' or octet_length(p_answers::text)>200000 then raise exception 'Provide a bounded answer object and a retry key';end if;
 payload:=jsonb_build_object('answers',p_answers,'submit',p_submit,'version',p_version);
 select * into retry from performance_internal.review_retry_state where reviewer_id=r.id;
 if retry.request_id=p_request then if retry.payload<>payload then raise exception 'This retry key was already used for different review details';end if;return jsonb_build_object('draft_version',r.draft_version,'status',r.status);end if;
 if not performance_internal.stage_writer(r.id) or p_version is null or p_version<>r.draft_version then raise exception 'The stage or saved version changed. Reload before saving; your local draft has not been applied';end if;
 for k,a in select key,value from jsonb_each(p_answers) loop perform performance_internal.validate_answer(i.id,k::uuid,a,p_submit);end loop;
 delete from public.appraisal_responses where reviewer_id=r.id;
 for k,a in select key,value from jsonb_each(p_answers) loop
  if a is not null and a not in('null'::jsonb,'""'::jsonb) then insert into public.appraisal_responses(instance_id,reviewer_id,question_id,response_json,response_text,response_numeric) values(i.id,r.id,k::uuid,a,case when jsonb_typeof(a)='string' then a#>>'{}' when jsonb_typeof(a)='boolean' then case when a='true'::jsonb then 'Yes' else 'No' end end,case when jsonb_typeof(a)='number' then (a#>>'{}')::numeric end);end if;
 end loop;
 update public.appraisal_reviewers set draft_version=draft_version+1 where id=r.id returning * into r;
 insert into performance_internal.review_retry_state(reviewer_id,request_id,payload) values(r.id,p_request,payload) on conflict(reviewer_id) do update set request_id=excluded.request_id,payload=excluded.payload;
 if p_submit then i:=performance_internal.submit_stage(r.id);end if;
 return jsonb_build_object('draft_version',r.draft_version,'status',case when p_submit then 'submitted' else r.status end);
end; $$;
create function public.save_appraisal_review(p_reviewer_id uuid,p_answers jsonb,p_expected_version integer,p_client_request_id uuid,p_submit boolean default false) returns jsonb language sql security invoker set search_path='' as $$ select performance_internal.save_review(p_reviewer_id,p_answers,p_expected_version,p_client_request_id,p_submit); $$;
create function performance_internal.submit_legacy(p_instance uuid) returns public.appraisal_instances language plpgsql security definer set search_path='' as $$ declare r uuid;i public.appraisal_instances;begin
 i:=performance_internal.lock_instance(p_instance);select id into r from public.appraisal_reviewers where instance_id=i.id and reviewer_user_id=auth.uid() and status='pending' order by sequence,id limit 1;
 if r is null then if exists(select 1 from public.appraisal_reviewers where instance_id=i.id and reviewer_user_id=auth.uid() and status='submitted' and performance_internal.reviewer_valid(id)) then return i;end if;raise exception 'No pending review stage is assigned to you';end if;return performance_internal.submit_stage(r);
end; $$;
create or replace function public.submit_appraisal(p_instance_id uuid) returns public.appraisal_instances language sql security invoker set search_path='' as $$ select * from performance_internal.submit_legacy(p_instance_id); $$;

create function performance_internal.record_guard() returns trigger language plpgsql security definer set search_path='' as $$ declare r public.appraisal_reviewers;q jsonb;begin
 if tg_table_name='appraisal_responses' then
  if tg_op='DELETE' then select * into r from public.appraisal_reviewers where id=old.reviewer_id;else select * into r from public.appraisal_reviewers where id=new.reviewer_id;end if;
  if r.status<>'pending' then raise exception 'Submitted reviews are immutable; add a visible HR amendment';end if;
  if tg_op<>'DELETE' then
   if new.instance_id<>r.instance_id then raise exception 'Response, stage and checkpoint must match';end if;
   perform performance_internal.validate_answer(new.instance_id,new.question_id,new.response_json,false);
  end if;
 elsif tg_table_name='appraisal_instances' then
  if tg_op='INSERT' then
   if not exists(select 1 from public.employees where id=new.employee_id and organization_id=new.organization_id) or not exists(select 1 from public.appraisal_templates where id=new.template_id and organization_id=new.organization_id) then raise exception 'Performance subject and template must belong to the organization';end if;
   if new.form_snapshot is null then new.form_snapshot:=performance_internal.template_snapshot(new.template_id);end if;
  else
   if tg_op='DELETE' then raise exception 'Performance records cannot be deleted';end if;
   if (to_jsonb(new)-'status'-'acknowledged_at'-'released_at'-'cancel_reason'-'query_status') is distinct from (to_jsonb(old)-'status'-'acknowledged_at'-'released_at'-'cancel_reason'-'query_status') then raise exception 'Checkpoint identity and questions are immutable';end if;
   if old.status in('complete','cancelled') and (to_jsonb(new)-'query_status') is distinct from(to_jsonb(old)-'query_status') then raise exception 'A completed or cancelled checkpoint cannot be rewritten';end if;
  end if;
 else
  if tg_op='DELETE' then raise exception 'Reviewer history cannot be deleted';end if;
  if tg_op='UPDATE' then
   if new.instance_id<>old.instance_id or new.reviewer_user_id is distinct from old.reviewer_user_id or new.role<>old.role or new.sequence<>old.sequence then raise exception 'Retain reviewer history; use the reassignment workflow';end if;
   if old.status in('submitted','skipped') and to_jsonb(new) is distinct from to_jsonb(old) then raise exception 'Closed review stages are immutable';end if;
  end if;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end; $$;
create trigger performance_response_integrity before insert or update or delete on public.appraisal_responses for each row execute function performance_internal.record_guard();
create trigger performance_instance_integrity before insert or update or delete on public.appraisal_instances for each row execute function performance_internal.record_guard();
create trigger performance_reviewer_integrity before update or delete on public.appraisal_reviewers for each row execute function performance_internal.record_guard();

create table public.appraisal_messages(id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.appraisal_instances(id),organization_id uuid not null references public.organizations(id),kind text not null check(kind in('employee_comment','hr_response','amendment')),body text not null,created_by uuid not null references auth.users(id),actor_name text not null,client_request_id uuid not null,resolve_query boolean not null default false,created_at timestamptz not null default now(),unique(created_by,client_request_id));
alter table public.appraisal_messages enable row level security;
create index appraisal_messages_instance_idx on public.appraisal_messages(instance_id,created_at,id);
create policy "shared released performance messages" on public.appraisal_messages for select to authenticated using(performance_internal.reader(instance_id) and exists(select 1 from public.appraisal_instances where id=instance_id and released_at is not null));
revoke all on public.appraisal_messages from public,anon,authenticated;grant select on public.appraisal_messages to authenticated;
create function performance_internal.message(p_instance uuid,p_kind text,p_body text,p_request uuid,p_resolve boolean) returns public.appraisal_messages language plpgsql security definer set search_path='' as $$ declare i public.appraisal_instances;m public.appraisal_messages;subject boolean;actor text;begin
 i:=performance_internal.lock_instance(p_instance);subject:=exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid());
 if i.released_at is null or p_kind is null or p_kind not in('employee_comment','hr_response','amendment') or p_request is null or p_resolve is null or length(trim(coalesce(p_body,''))) not between 3 and 4000 then raise exception 'Add a shared comment to released feedback, with 3–4000 characters';end if;
 if p_kind='employee_comment' then if not subject then raise exception 'Only the employee may record their response';end if;elsif not performance_internal.hr(i.organization_id) or subject then raise exception 'Another authorised HR colleague must respond or amend this checkpoint';end if;
 select * into m from public.appraisal_messages where created_by=auth.uid() and client_request_id=p_request;
 if m.id is not null then if m.instance_id<>i.id or m.kind<>p_kind or m.body<>trim(p_body) or m.resolve_query<>p_resolve then raise exception 'Retry key already used for a different message';end if;return m;end if;
 select concat_ws(' ',coalesce(nullif(trim(preferred_name),''),first_name),last_name) into actor from public.employees where organization_id=i.organization_id and user_id=auth.uid() limit 1;
 insert into public.appraisal_messages(instance_id,organization_id,kind,body,created_by,actor_name,client_request_id,resolve_query) values(i.id,i.organization_id,p_kind,trim(p_body),auth.uid(),actor,p_request,p_resolve) returning * into m;
 update public.appraisal_instances set query_status=case when p_kind='employee_comment' then 'open' when p_resolve then 'resolved' else query_status end where id=i.id;
 perform private.log_audit_event(i.organization_id,'PERFORMANCE_SHARED_MESSAGE','appraisal_instance',i.id,null,jsonb_build_object('message_id',m.id,'kind',p_kind));return m;
end; $$;
create function public.add_performance_message(p_instance_id uuid,p_kind text,p_body text,p_client_request_id uuid,p_resolve boolean default false) returns public.appraisal_messages language sql security invoker set search_path='' as $$ select * from performance_internal.message(p_instance_id,p_kind,p_body,p_client_request_id,p_resolve); $$;
create function performance_internal.acknowledge(p_instance uuid,p_disposition text,p_note text) returns public.appraisal_instances language plpgsql security definer set search_path='' as $$ declare i public.appraisal_instances;begin
 i:=performance_internal.lock_instance(p_instance);
 if not exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()) or not private.has_permission(i.organization_id,'appraisal.complete_self') then raise exception 'Only the employee may acknowledge receipt';end if;
 if p_disposition is null or p_disposition not in('received','received_with_comments','disagree') or length(coalesce(p_note,''))>4000 or (p_disposition<>'received' and length(trim(coalesce(p_note,'')))<3) then raise exception 'Select a receipt response and explain any comments or disagreement';end if;
 if i.status='complete' then return i;end if;if i.status<>'employee_acknowledgement' or i.released_at is null then raise exception 'Feedback is not ready for acknowledgement';end if;
 insert into public.appraisal_signoffs(instance_id,signed_by_user_id,role,note,disposition) values(i.id,auth.uid(),'employee',nullif(trim(p_note),''),p_disposition);
 update public.appraisal_instances set status='complete',acknowledged_at=now(),query_status=case when p_disposition='disagree' then 'open' else query_status end where id=i.id returning * into i;
 perform private.log_audit_event(i.organization_id,'APPRAISAL_ACKNOWLEDGED','appraisal_instance',i.id,null,jsonb_build_object('disposition',p_disposition));return i;
end; $$;
create function public.record_performance_receipt(p_instance_id uuid,p_disposition text,p_note text default null) returns public.appraisal_instances language sql security invoker set search_path='' as $$ select * from performance_internal.acknowledge(p_instance_id,p_disposition,p_note); $$;
create or replace function public.acknowledge_appraisal(p_instance_id uuid,p_note text default null) returns public.appraisal_instances language sql security invoker set search_path='' as $$ select * from performance_internal.acknowledge(p_instance_id,'received',p_note); $$;

create function performance_internal.resolve_reviewer(p_reviewer uuid,p_employee uuid,p_reason text,p_waive boolean) returns public.appraisal_instances language plpgsql security definer set search_path='' as $$ declare old_stage public.appraisal_reviewers;i public.appraisal_instances;e public.employees;replacement public.appraisal_reviewers;begin
 select * into old_stage from public.appraisal_reviewers where id=p_reviewer;i:=performance_internal.lock_instance(old_stage.instance_id);perform performance_internal.require_hr(i.organization_id);select * into old_stage from public.appraisal_reviewers where id=p_reviewer for update;
 if exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()) then raise exception 'Another HR colleague must administer your review stages';end if;
 if old_stage.status<>'pending' or i.status in('complete','cancelled') or length(trim(coalesce(p_reason,''))) not between 3 and 1000 or p_waive is null then raise exception 'Choose an open review stage and explain the reassignment or waiver';end if;
 if p_waive and old_stage.role<>'self' and not exists(select 1 from public.appraisal_reviewers where instance_id=i.id and id<>old_stage.id and role<>'self' and status in('pending','submitted')) then raise exception 'Retain at least one independent review stage';end if;
 if not p_waive then
  select * into e from public.employees where id=p_employee and organization_id=i.organization_id and status in('active','leave') and user_id is not null;
  if e.id is null or (old_stage.role='self' and e.id<>i.employee_id) or (old_stage.role<>'self' and e.id=i.employee_id) then raise exception 'Choose an eligible independent reviewer; self-review stays with the employee';end if;
  if exists(select 1 from public.appraisal_reviewers where instance_id=i.id and id<>old_stage.id and reviewer_user_id=e.user_id and status<>'skipped') then raise exception 'This person already has a review stage on the checkpoint';end if;
 end if;
 update public.appraisal_reviewers set status='skipped',resolution_reason=trim(p_reason) where id=old_stage.id;
 if not p_waive then
  insert into public.appraisal_reviewers(instance_id,role,reviewer_user_id,sequence,reviewer_name,due_date) values(i.id,old_stage.role,e.user_id,old_stage.sequence,concat_ws(' ',coalesce(nullif(trim(e.preferred_name),''),e.first_name),e.last_name),old_stage.due_date) returning * into replacement;
  if not performance_internal.reviewer_valid(replacement.id) then raise exception 'Reviewer needs the relevant performance permission and management scope';end if;
 end if;
 perform private.log_audit_event(i.organization_id,'PERFORMANCE_REVIEWER_RESOLVED','appraisal_instance',i.id,null,jsonb_build_object('old_stage',old_stage.id,'replacement',replacement.id,'waived',p_waive,'reason',trim(p_reason)));return performance_internal.advance(i.id);
end; $$;
create function public.resolve_performance_reviewer(p_reviewer_id uuid,p_employee_id uuid,p_reason text,p_waive boolean default false) returns public.appraisal_instances language sql security invoker set search_path='' as $$ select * from performance_internal.resolve_reviewer(p_reviewer_id,p_employee_id,p_reason,p_waive); $$;
create function performance_internal.cycle_action(p_cycle uuid,p_action text,p_reason text) returns public.appraisal_cycles language plpgsql security definer set search_path='' as $$ declare c public.appraisal_cycles;begin
 select * into c from public.appraisal_cycles where id=p_cycle for update;perform performance_internal.require_hr(c.organization_id);
 if p_action is null or p_action not in('close','cancel') or length(trim(coalesce(p_reason,''))) not between 3 and 1000 then raise exception 'Choose a cycle outcome and explain it';end if;
 if c.status in('closed','cancelled') then return c;end if;
 if p_action='close' and (c.status<>'open' or exists(select 1 from public.appraisal_instances where cycle_id=c.id and status not in('complete','cancelled'))) then raise exception 'Resolve every checkpoint before closing the cycle';end if;
 if p_action='cancel' then update public.appraisal_instances set status='cancelled',cancel_reason=trim(p_reason) where cycle_id=c.id and status not in('complete','cancelled');end if;
 update public.appraisal_cycles set status=case when p_action='close' then 'closed' else 'cancelled' end,cancel_reason=trim(p_reason),closed_at=now() where id=c.id returning * into c;
 perform private.log_audit_event(c.organization_id,'PERFORMANCE_CYCLE_RESOLVED','appraisal_cycle',c.id,null,jsonb_build_object('action',p_action,'reason',trim(p_reason)));return c;
end; $$;
create function public.resolve_performance_cycle(p_cycle_id uuid,p_action text,p_reason text) returns public.appraisal_cycles language sql security invoker set search_path='' as $$ select * from performance_internal.cycle_action(p_cycle_id,p_action,p_reason); $$;

create table public.performance_goals(id uuid primary key default gen_random_uuid(),instance_id uuid not null references public.appraisal_instances(id),organization_id uuid not null references public.organizations(id),employee_id uuid not null references public.employees(id),title text not null,measure text not null,target_date date not null,support text,status text not null default 'proposed' check(status in('proposed','active','completed','cancelled')),progress integer not null default 0 check(progress between 0 and 100),version integer not null default 1,created_by uuid not null references auth.users(id),created_at timestamptz not null default now(),agreed_by uuid references auth.users(id),agreed_at timestamptz,completed_at timestamptz,source_response_id uuid unique references public.appraisal_responses(id),client_request_id uuid,creation_payload jsonb,unique(created_by,client_request_id));
create table public.performance_goal_events(id uuid primary key default gen_random_uuid(),goal_id uuid not null references public.performance_goals(id),instance_id uuid not null references public.appraisal_instances(id),kind text not null,note text not null,progress integer not null,prior_values jsonb,created_by uuid not null references auth.users(id),actor_name text not null,created_at timestamptz not null default now());
alter table public.performance_goals enable row level security;alter table public.performance_goal_events enable row level security;
create index performance_goal_instance_idx on public.performance_goals(instance_id,created_at);
create index performance_goal_event_goal_idx on public.performance_goal_events(goal_id,created_at);
create policy "shared performance goals" on public.performance_goals for select to authenticated using(performance_internal.reader(instance_id));
create policy "shared performance goal history" on public.performance_goal_events for select to authenticated using(performance_internal.reader(instance_id));
revoke all on public.performance_goals,public.performance_goal_events from public,anon,authenticated;grant select on public.performance_goals,public.performance_goal_events to authenticated;
create function performance_internal.leader(p_instance uuid) returns boolean language sql stable security definer set search_path='' as $$ select exists(select 1 from public.appraisal_instances i where i.id=p_instance and performance_internal.member(i.organization_id) and not exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()) and (performance_internal.hr(i.organization_id) or (private.has_permission(i.organization_id,'appraisal.review_direct_reports') and private.in_management_scope(i.employee_id)))); $$;
create function performance_internal.goal_action(p_instance uuid,p_goal uuid,p_action text,p_data jsonb,p_version integer,p_request uuid) returns public.performance_goals language plpgsql security definer set search_path='' as $$ declare i public.appraisal_instances;g public.performance_goals;prior jsonb;subject boolean;lead boolean;actor text;note text;begin
 i:=performance_internal.lock_instance(p_instance);subject:=exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid());lead:=performance_internal.leader(i.id);
 if not(subject or lead) or p_action is null or p_action not in('propose','edit','agree','progress','complete','cancel') or p_data is null or jsonb_typeof(p_data)<>'object' or octet_length(p_data::text)>20000 then raise exception 'Goal changes require the employee or an independent performance leader';end if;
 note:=trim(coalesce(p_data->>'note',''));if length(note) not between 3 and 2000 then raise exception 'Explain the goal update in 3–2000 characters';end if;
 if p_action in('propose','edit') and (exists(select 1 from jsonb_each(p_data) f where f.key in('title','measure','target_date','support') and f.value<>'null'::jsonb and jsonb_typeof(f.value)<>'string') or length(coalesce(p_data->>'support',''))>2000) then raise exception 'Use text goal fields and up to 2000 characters of support';end if;
 if p_action='propose' then
  if p_request is null then raise exception 'A goal retry key is required';end if;select * into g from public.performance_goals where created_by=auth.uid() and client_request_id=p_request;
  if g.id is not null then if g.instance_id<>i.id or g.title<>trim(p_data->>'title') or g.measure<>trim(p_data->>'measure') or g.target_date is distinct from private.safe_import_date(p_data->>'target_date') or g.creation_payload is distinct from p_data then raise exception 'Retry key used for a different goal';end if;return g;end if;
  if (select count(*) from public.performance_goals where instance_id=i.id)>=100 then raise exception 'This checkpoint already has 100 development goals';end if;
  if length(trim(coalesce(p_data->>'title',''))) not between 3 and 200 or length(trim(coalesce(p_data->>'measure',''))) not between 3 and 2000 or private.safe_import_date(p_data->>'target_date') is null or length(coalesce(p_data->>'support',''))>2000 then raise exception 'Goals need a title, measurable outcome, target date and optional support';end if;
  insert into public.performance_goals(instance_id,organization_id,employee_id,title,measure,target_date,support,created_by,client_request_id,creation_payload) values(i.id,i.organization_id,i.employee_id,trim(p_data->>'title'),trim(p_data->>'measure'),private.safe_import_date(p_data->>'target_date'),nullif(trim(p_data->>'support'),''),auth.uid(),p_request,p_data) returning * into g;
 else
  select * into g from public.performance_goals where id=p_goal and instance_id=i.id for update;
  if g.id is null or p_version is null or g.version<>p_version then raise exception 'Goal changed. Reload before updating';end if;
  if g.status in('completed','cancelled') then raise exception 'This goal is closed; propose a new goal rather than rewrite history';end if;prior:=to_jsonb(g);
  if p_action in('agree','complete') and not lead then raise exception 'An independent performance leader must agree or confirm completion';end if;
  if p_action='agree' then if g.status<>'proposed' then raise exception 'This goal has already been agreed';end if;update public.performance_goals set status='active',agreed_by=auth.uid(),agreed_at=now(),version=version+1 where id=g.id returning * into g;
  elsif p_action='complete' then if g.status<>'active' then raise exception 'Agree the goal before confirming completion';end if;update public.performance_goals set status='completed',progress=100,completed_at=now(),version=version+1 where id=g.id returning * into g;
  elsif p_action='progress' then if g.status<>'active' or jsonb_typeof(p_data->'progress') is distinct from 'number' or (p_data->>'progress')::numeric<>trunc((p_data->>'progress')::numeric) or (p_data->>'progress')::numeric not between 0 and 100 then raise exception 'Update an active goal with progress from 0 to 100';end if;update public.performance_goals set progress=(p_data->>'progress')::integer,version=version+1 where id=g.id returning * into g;
  elsif p_action='cancel' then if not lead and not(g.status='proposed' and g.created_by=auth.uid()) then raise exception 'Only a leader may cancel an agreed goal';end if;update public.performance_goals set status='cancelled',version=version+1 where id=g.id returning * into g;
  else
   if not lead and not(g.status='proposed' and g.created_by=auth.uid()) then raise exception 'Agreed goals need a leader to change their terms';end if;
   if length(trim(coalesce(p_data->>'title',''))) not between 3 and 200 or length(trim(coalesce(p_data->>'measure',''))) not between 3 and 2000 or private.safe_import_date(p_data->>'target_date') is null then raise exception 'Check the goal title, measurable outcome and target date';end if;
   update public.performance_goals set title=trim(p_data->>'title'),measure=trim(p_data->>'measure'),target_date=private.safe_import_date(p_data->>'target_date'),support=nullif(trim(p_data->>'support'),''),version=version+1 where id=g.id returning * into g;
  end if;
 end if;
 select concat_ws(' ',coalesce(nullif(trim(preferred_name),''),first_name),last_name) into actor from public.employees where organization_id=i.organization_id and user_id=auth.uid() limit 1;
 insert into public.performance_goal_events(goal_id,instance_id,kind,note,progress,prior_values,created_by,actor_name) values(g.id,i.id,p_action,note,g.progress,prior,auth.uid(),actor);
 perform private.log_audit_event(i.organization_id,'PERFORMANCE_GOAL_UPDATED','performance_goal',g.id,null,jsonb_build_object('action',p_action,'version',g.version));return g;
end; $$;
create function public.update_performance_goal(p_instance_id uuid,p_goal_id uuid,p_action text,p_data jsonb,p_expected_version integer default null,p_client_request_id uuid default null) returns public.performance_goals language sql security invoker set search_path='' as $$ select * from performance_internal.goal_action(p_instance_id,p_goal_id,p_action,p_data,p_expected_version,p_client_request_id); $$;

create function performance_internal.detail(p_instance uuid) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare i public.appraisal_instances;r public.appraisal_reviewers;begin
 select * into i from public.appraisal_instances where id=p_instance;if i.id is null or not performance_internal.reader(i.id) then raise exception using errcode='42501',message='Performance checkpoint unavailable';end if;
 select * into r from public.appraisal_reviewers where instance_id=i.id and status='pending' order by sequence,id limit 1;
 return to_jsonb(i)||jsonb_build_object('is_subject',exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()),'can_admin',performance_internal.hr(i.organization_id),'can_lead',performance_internal.leader(i.id),'current_stage_id',r.id,'reviewers',coalesce((select jsonb_agg(to_jsonb(ar)||jsonb_build_object('is_mine',ar.reviewer_user_id=auth.uid(),'can_edit',performance_internal.stage_writer(ar.id),'eligible',performance_internal.reviewer_valid(ar.id)) order by ar.sequence,ar.id) from public.appraisal_reviewers ar where instance_id=i.id),'[]'::jsonb),
 'responses',coalesce((select jsonb_agg(to_jsonb(a)) from public.appraisal_responses a where a.instance_id=i.id and performance_internal.response_reader(a.reviewer_id)),'[]'::jsonb),
 'signoffs',coalesce((select jsonb_agg(to_jsonb(s) order by signed_at,id) from public.appraisal_signoffs s where s.instance_id=i.id),'[]'::jsonb),
 'messages',case when i.released_at is not null then coalesce((select jsonb_agg(to_jsonb(m) order by created_at,id) from public.appraisal_messages m where instance_id=i.id),'[]'::jsonb) else '[]'::jsonb end,
 'goals',coalesce((select jsonb_agg(to_jsonb(g)||jsonb_build_object('events',coalesce((select jsonb_agg(to_jsonb(e) order by created_at,id) from public.performance_goal_events e where goal_id=g.id),'[]'::jsonb)) order by g.created_at,g.id) from public.performance_goals g where instance_id=i.id),'[]'::jsonb),
 'previous',(select jsonb_build_object('id',p.id,'label',p.label,'review_period_start',p.review_period_start,'review_period_end',p.review_period_end) from public.appraisal_instances p where p.employee_id=i.employee_id and p.id<>i.id and p.released_at is not null and p.created_at<i.created_at and performance_internal.reader(p.id) order by p.created_at desc,p.id limit 1));
end; $$;
create function public.get_performance_checkpoint(p_instance_id uuid) returns jsonb language sql security invoker set search_path='' as $$ select performance_internal.detail(p_instance_id); $$;
create function performance_internal.work(p_org uuid,p_view text,p_page integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ begin
 if not performance_internal.member(p_org) then raise exception 'Performance access unavailable';end if;if p_view is null or p_view not in('active','history','all') or p_page is null or p_page not between 1 and 100000 then raise exception 'Invalid performance view';end if;
 return jsonb_build_object('total',(select count(*) from public.appraisal_instances i where organization_id=p_org and performance_internal.reader(i.id) and (exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()) or exists(select 1 from public.appraisal_reviewers r where r.instance_id=i.id and reviewer_user_id=auth.uid() and performance_internal.reviewer_valid(r.id))) and (p_view='all' or(p_view='active' and i.status not in('complete','cancelled')) or(p_view='history' and i.status in('complete','cancelled')))),
 'active_count',(select count(*) from public.appraisal_instances i join public.employees e on e.id=i.employee_id where i.organization_id=p_org and e.user_id=auth.uid() and i.status not in('complete','cancelled')),
 'ready_count',(select count(*) from public.appraisal_reviewers r join public.appraisal_instances i on i.id=r.instance_id where i.organization_id=p_org and r.reviewer_user_id=auth.uid() and performance_internal.stage_writer(r.id)),
 'items',coalesce((select jsonb_agg(to_jsonb(x)) from(select i.id,i.label,i.employee_name,i.status,i.review_period_start,i.review_period_end,i.created_at,i.query_status,exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()) is_subject,(select r.role from public.appraisal_reviewers r where r.instance_id=i.id and r.reviewer_user_id=auth.uid() and r.status='pending' and performance_internal.reviewer_valid(r.id) order by sequence,id limit 1) my_role,(select r.due_date from public.appraisal_reviewers r where r.instance_id=i.id and r.reviewer_user_id=auth.uid() and r.status='pending' and performance_internal.reviewer_valid(r.id) order by sequence,id limit 1) due_date from public.appraisal_instances i where i.organization_id=p_org and performance_internal.reader(i.id) and (exists(select 1 from public.employees where id=i.employee_id and user_id=auth.uid()) or exists(select 1 from public.appraisal_reviewers r where r.instance_id=i.id and reviewer_user_id=auth.uid() and performance_internal.reviewer_valid(r.id))) and(p_view='all' or(p_view='active' and i.status not in('complete','cancelled')) or(p_view='history' and i.status in('complete','cancelled'))) order by i.created_at desc,i.id limit 20 offset(p_page-1)*20)x),'[]'::jsonb));
end; $$;
create function public.list_performance_work(p_organization_id uuid,p_view text default 'active',p_page integer default 1) returns jsonb language sql security invoker set search_path='' as $$ select performance_internal.work(p_organization_id,p_view,p_page); $$;
create function performance_internal.ready(p_org uuid) returns table(id uuid,instance_id uuid,role text,employee_name text,due_date date) language sql stable security definer set search_path='' as $$ select r.id,r.instance_id,r.role,i.employee_name,r.due_date from public.appraisal_reviewers r join public.appraisal_instances i on i.id=r.instance_id where i.organization_id=p_org and r.reviewer_user_id=auth.uid() and performance_internal.stage_writer(r.id) order by r.due_date nulls last,r.id limit 4; $$;
create function public.list_my_performance_reviews(p_organization_id uuid) returns table(id uuid,instance_id uuid,role text,employee_name text,due_date date) language sql security invoker set search_path='' as $$ select * from performance_internal.ready(p_organization_id); $$;

create function performance_internal.save_cycle(p_org uuid,p_id uuid,p_data jsonb,p_revision integer) returns public.appraisal_cycles language plpgsql security definer set search_path='' as $$ declare c public.appraisal_cycles;begin
 perform performance_internal.require_hr(p_org);if p_data is null or jsonb_typeof(p_data)<>'object' or private.safe_import_date(p_data->>'start_date') is null or private.safe_import_date(p_data->>'review_period_start') is null or private.safe_import_date(p_data->>'review_period_end') is null then raise exception 'Provide the review period and cycle opening date';end if;perform performance_internal.validate_filter(p_org,coalesce(p_data->'employee_filter','{}'::jsonb));
 if p_id is null then insert into public.appraisal_cycles(organization_id,template_id,name,start_date,review_period_start,review_period_end,self_review_due,supervisor_review_due,manager_review_due,acknowledgement_due,employee_filter,created_by) values(p_org,(p_data->>'template_id')::uuid,p_data->>'name',(p_data->>'start_date')::date,(p_data->>'review_period_start')::date,(p_data->>'review_period_end')::date,nullif(p_data->>'self_review_due','')::date,nullif(p_data->>'supervisor_review_due','')::date,nullif(p_data->>'manager_review_due','')::date,nullif(p_data->>'acknowledgement_due','')::date,coalesce(p_data->'employee_filter','{}'),auth.uid()) returning * into c;
 else select * into c from public.appraisal_cycles where id=p_id and organization_id=p_org for update;if c.id is null or c.status<>'draft' or p_revision is null or c.revision<>p_revision then raise exception 'Draft cycle changed. Reload before editing';end if;
 update public.appraisal_cycles set template_id=(p_data->>'template_id')::uuid,name=p_data->>'name',start_date=(p_data->>'start_date')::date,review_period_start=(p_data->>'review_period_start')::date,review_period_end=(p_data->>'review_period_end')::date,self_review_due=nullif(p_data->>'self_review_due','')::date,supervisor_review_due=nullif(p_data->>'supervisor_review_due','')::date,manager_review_due=nullif(p_data->>'manager_review_due','')::date,acknowledgement_due=nullif(p_data->>'acknowledgement_due','')::date,employee_filter=coalesce(p_data->'employee_filter','{}'),revision=revision+1 where id=c.id returning * into c;end if;
 perform private.log_audit_event(p_org,'PERFORMANCE_CYCLE_SAVED','appraisal_cycle',c.id,null,jsonb_build_object('revision',c.revision));return c;
end; $$;
create function public.save_performance_cycle(p_organization_id uuid,p_cycle_id uuid,p_data jsonb,p_expected_revision integer default null) returns public.appraisal_cycles language sql security invoker set search_path='' as $$ select * from performance_internal.save_cycle(p_organization_id,p_cycle_id,p_data,p_expected_revision); $$;
create function public.preview_performance_roster(p_cycle_id uuid) returns table(employee_id uuid,employee_name text,user_id uuid,supervisor_user uuid,manager_user uuid,warning text) language sql security invoker set search_path='' as $$ select * from performance_internal.roster(p_cycle_id); $$;
create function performance_internal.people(p_org uuid) returns table(id uuid,label text) language plpgsql stable security definer set search_path='' as $$ begin if not performance_internal.hr(p_org) then raise exception 'Performance administration permission required';end if;return query select e.id,concat_ws(' ',coalesce(nullif(trim(e.preferred_name),''),e.first_name),e.last_name)||' ('||e.employee_number||')' from public.employees e where e.organization_id=p_org and e.status in('active','leave') and e.user_id is not null order by e.last_name,e.first_name,e.id;end; $$;
create function public.list_performance_people(p_organization_id uuid) returns table(id uuid,label text) language sql security invoker set search_path='' as $$ select * from performance_internal.people(p_organization_id); $$;
create function performance_internal.admin(p_org uuid,p_page integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ begin
 if not performance_internal.hr(p_org) then raise exception 'Performance administration permission required';end if;if p_page is null or p_page not between 1 and 100000 then raise exception 'Invalid cycle page';end if;
 return jsonb_build_object('total',(select count(*) from public.appraisal_cycles where organization_id=p_org),'cycles',coalesce((select jsonb_agg(to_jsonb(x)) from(select c.*,(select count(*) from public.appraisal_instances where cycle_id=c.id) total_instances,(select count(*) from public.appraisal_instances where cycle_id=c.id and status='complete') completed_instances,(select count(*) from public.appraisal_instances where cycle_id=c.id and status='cancelled') cancelled_instances,(select count(*) from public.appraisal_instances where cycle_id=c.id and query_status='open') open_queries,(select count(*) from public.appraisal_reviewers r join public.appraisal_instances i on i.id=r.instance_id where i.cycle_id=c.id and i.status not in('complete','cancelled') and r.status='pending' and not performance_internal.reviewer_valid(r.id)) blocked_reviewers from public.appraisal_cycles c where organization_id=p_org order by c.created_at desc,c.id limit 20 offset(p_page-1)*20)x),'[]'::jsonb));end; $$;
create function public.get_performance_admin(p_organization_id uuid,p_page integer default 1) returns jsonb language sql security invoker set search_path='' as $$ select performance_internal.admin(p_organization_id,p_page); $$;
create function performance_internal.cycle_detail(p_id uuid,p_page integer,p_query text) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare c public.appraisal_cycles;begin
 select * into c from public.appraisal_cycles where id=p_id;if not performance_internal.hr(c.organization_id) then raise exception 'Performance administration permission required';end if;if p_page is null or p_page not between 1 and 100000 or length(coalesce(p_query,''))>120 then raise exception 'Invalid checkpoint filter';end if;
 return to_jsonb(c)||jsonb_build_object('total',(select count(*) from public.appraisal_instances where cycle_id=c.id and employee_name ilike '%'||trim(coalesce(p_query,''))||'%'),'instances',coalesce((select jsonb_agg(to_jsonb(x)) from(select i.id,i.employee_name,i.status,i.released_at,i.query_status,r.role current_role,r.due_date,r.reviewer_name,case when r.status='pending' then not performance_internal.reviewer_valid(r.id) else false end reviewer_blocked from public.appraisal_instances i left join lateral(select * from public.appraisal_reviewers where instance_id=i.id and status='pending' order by sequence,id limit 1)r on true where i.cycle_id=c.id and i.employee_name ilike '%'||trim(coalesce(p_query,''))||'%' order by i.employee_name,i.id limit 25 offset(p_page-1)*25)x),'[]'::jsonb));end; $$;
create function public.get_performance_cycle(p_cycle_id uuid,p_page integer default 1,p_query text default '') returns jsonb language sql security invoker set search_path='' as $$ select performance_internal.cycle_detail(p_cycle_id,p_page,p_query); $$;
create function performance_internal.template_org(p_template uuid) returns uuid language sql stable security definer set search_path='' as $$ select organization_id from public.appraisal_templates where id=p_template; $$;
create function performance_internal.section_org(p_section uuid) returns uuid language sql stable security definer set search_path='' as $$ select t.organization_id from public.appraisal_sections s join public.appraisal_templates t on t.id=s.template_id where s.id=p_section; $$;
create policy "performance template account security" on public.appraisal_templates as restrictive for all to authenticated using(performance_internal.member(organization_id)) with check(performance_internal.member(organization_id));
create policy "performance section account security" on public.appraisal_sections as restrictive for all to authenticated using(performance_internal.member(performance_internal.template_org(template_id))) with check(performance_internal.member(performance_internal.template_org(template_id)));
create policy "performance question account security" on public.appraisal_questions as restrictive for all to authenticated using(performance_internal.member(performance_internal.section_org(section_id))) with check(performance_internal.member(performance_internal.section_org(section_id)));
drop policy "HR creates performance cycles" on public.appraisal_cycles;drop policy "HR edits performance cycles" on public.appraisal_cycles;revoke insert,update,delete on public.appraisal_cycles from authenticated;
revoke all on all functions in schema performance_internal from public,anon,authenticated;
do $$ declare f record;begin
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='performance_internal' and p.proname=any(array['member','hr','reader','response_reader','reviewer_valid','stage_writer','template_org','section_org','launch','save_review','submit_legacy','message','acknowledge','resolve_reviewer','cycle_action','leader','goal_action','detail','work','ready','save_cycle','roster','people','admin','cycle_detail']) loop execute format('grant execute on function %s to authenticated',f.signature);end loop;
 for f in select p.oid::regprocedure signature from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and(p.proname in('launch_appraisal_cycle','submit_appraisal','acknowledge_appraisal','save_appraisal_review') or p.proname like '%performance%') loop execute format('revoke all on function %s from public,anon',f.signature);execute format('grant execute on function %s to authenticated',f.signature);end loop;end $$;

create function performance_internal.append_only() returns trigger language plpgsql security definer set search_path='' as $$ begin raise exception 'Performance decisions and shared history are append-only';end; $$;
create trigger performance_message_history before update or delete on public.appraisal_messages for each row execute function performance_internal.append_only();
create trigger performance_signoff_history before update or delete on public.appraisal_signoffs for each row execute function performance_internal.append_only();
create trigger performance_goal_event_history before update or delete on public.performance_goal_events for each row execute function performance_internal.append_only();
revoke all on function performance_internal.append_only() from public,anon,authenticated;

create function performance_internal.employee_history(p_employee uuid,p_page integer) returns jsonb language plpgsql stable security definer set search_path='' as $$ declare e public.employees;begin
 select * into e from public.employees where id=p_employee;if e.id is null or not performance_internal.member(e.organization_id) or not(coalesce(e.user_id=auth.uid(),false) or performance_internal.hr(e.organization_id) or (private.has_permission(e.organization_id,'appraisal.review_direct_reports') and private.in_management_scope(e.id))) then raise exception using errcode='42501',message='Employee performance history unavailable';end if;
 if p_page is null or p_page not between 1 and 100000 then raise exception 'Invalid performance history page';end if;
 return jsonb_build_object('employee_name',concat_ws(' ',coalesce(nullif(trim(e.preferred_name),''),e.first_name),e.last_name),'total',(select count(*) from public.appraisal_instances where employee_id=e.id),'items',coalesce((select jsonb_agg(to_jsonb(x)) from(select id,label,status,review_period_start,review_period_end,created_at,query_status from public.appraisal_instances where employee_id=e.id order by created_at desc,id limit 20 offset(p_page-1)*20)x),'[]'::jsonb));
end; $$;
create function public.list_employee_performance(p_employee_id uuid,p_page integer default 1) returns jsonb language sql security invoker set search_path='' as $$ select performance_internal.employee_history(p_employee_id,p_page); $$;
revoke all on function performance_internal.employee_history(uuid,integer),public.list_employee_performance(uuid,integer) from public,anon;grant execute on function performance_internal.employee_history(uuid,integer),public.list_employee_performance(uuid,integer) to authenticated;
